function localizedText(value,translation,field){
 const japanese=Array.isArray(value)?value[0]:value;
 const words=translation??common[japanese]??(Array.isArray(value)?value.slice(1):undefined);
 if(!Array.isArray(words)||words.length!==3||words.some(text=>typeof text!=='string'||!text.trim()))throw new Error('Missing diagnostic translation: '+field);
 return [japanese,...words];
}
export function localizeDiagnostics(japaneseNodes){
 return Object.fromEntries(Object.entries(japaneseNodes).map(([id,node])=>{
  const copy=translations[id];
  if(copy?.choices&&copy.choices.length>(node.choices?.length??0))throw new Error('Diagnostic choice count mismatch: '+id);
  if(copy?.observations&&copy.observations.length!==(node.observations?.length??0))throw new Error('Diagnostic observation count mismatch: '+id);
  return [id,{...node,title:localizedText(node.title,copy?.title,id+'.title'),body:localizedText(node.body,copy?.body,id+'.body'),
   ...(node.choices?{choices:node.choices.map((choice,index)=>({...choice,title:localizedText(choice.title,copy?.choices?.[index],id+'.choices.'+index)}))}:{}),
   ...(node.observations?{observations:node.observations.map((item,index)=>({...item,title:localizedText(item.title,copy?.observations?.[index]?.title,id+'.observations.'+index+'.title'),body:localizedText(item.body,copy?.observations?.[index]?.body,id+'.observations.'+index+'.body')}))}:{})}];
 }));
}
